"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[7129],{42114(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>c,frontMatter:()=>s,metadata:()=>r,toc:()=>d});var o=n(74848),a=n(28453);const s={title:"Where Does the Chaos Go? (2): The Monster Becomes a Seat",sidebar_label:"2. The Monster Becomes a Seat",slug:"/chaos-series/the-monster-becomes-a-seat",date:new Date("2026-11-23T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"chaos-series",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u91d1\u878d\u5316","legacy","\u7d44\u7e54","\u8209\u8b49\u8cac\u4efb","\u8077\u5834\u653f\u6cbb"],en:["financialization","legacy","organization","burden-of-proof","workplace-politics"]},keywords:["legacy","reference design","burden of proof","Gresham's Law","AI PC"],summary:"How a legacy system becomes a monster nobody understands over two decades, and then a seat nobody can take in a shrinking company.",description:"How a legacy system becomes a monster nobody understands over two decades, and then a seat nobody can take in a shrinking company.",status:"published",reading_time:19,series:{order:2}},i="Where Does the Chaos Go? (2): The Monster Becomes a Seat",r={id:"series/chaos-series/the-monster-becomes-a-seat",title:"Where Does the Chaos Go? (2): The Monster Becomes a Seat",description:"How a legacy system becomes a monster nobody understands over two decades, and then a seat nobody can take in a shrinking company.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/series/chaos-series/02-the-monster-becomes-a-seat.md",sourceDirName:"series/chaos-series",slug:"/chaos-series/the-monster-becomes-a-seat",permalink:"/en/docs/chaos-series/the-monster-becomes-a-seat",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:2,frontMatter:{title:"Where Does the Chaos Go? (2): The Monster Becomes a Seat",sidebar_label:"2. The Monster Becomes a Seat",slug:"/chaos-series/the-monster-becomes-a-seat",date:"2026-11-23T00:00:00.000Z",lang:"en",section:"sober-record",topic:"chaos-series",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u91d1\u878d\u5316","legacy","\u7d44\u7e54","\u8209\u8b49\u8cac\u4efb","\u8077\u5834\u653f\u6cbb"],en:["financialization","legacy","organization","burden-of-proof","workplace-politics"]},keywords:["legacy","reference design","burden of proof","Gresham's Law","AI PC"],summary:"How a legacy system becomes a monster nobody understands over two decades, and then a seat nobody can take in a shrinking company.",description:"How a legacy system becomes a monster nobody understands over two decades, and then a seat nobody can take in a shrinking company.",status:"published",reading_time:19,series:{order:2}},sidebar:"lucidRecord",previous:{title:"1. You Can't Have Both Freedom and Lossless Integration",permalink:"/en/docs/chaos-series/freedom-and-lossless-integration"},next:{title:"3. Each Time the Problem Gets Worse, Someone Gets Promoted",permalink:"/en/docs/chaos-series/problem-worse-person-promoted"}},h={},d=[{value:"A dream, a legacy system, and whether staying counts as winning",id:"a-dream-a-legacy-system-and-whether-staying-counts-as-winning",level:2},{value:"Prologue: A Sleeper Carriage",id:"prologue-a-sleeper-carriage",level:2},{value:"1. The Monster Was Not Always a Monster",id:"1-the-monster-was-not-always-a-monster",level:2},{value:"2. Why Outsiders Don&#39;t Believe You",id:"2-why-outsiders-dont-believe-you",level:2},{value:"3. The Monster Writes the Exam",id:"3-the-monster-writes-the-exam",level:2},{value:"4. Evidence Has to Be Bought With Time",id:"4-evidence-has-to-be-bought-with-time",level:2},{value:"5. The Documents Don&#39;t Match Reality",id:"5-the-documents-dont-match-reality",level:2},{value:"6. Evidence Requires Power",id:"6-evidence-requires-power",level:2},{value:"7. Bad Money Drives Out Good Only Under Certain Conditions",id:"7-bad-money-drives-out-good-only-under-certain-conditions",level:2},{value:"8. Whether People Fight Depends on Room",id:"8-whether-people-fight-depends-on-room",level:2},{value:"9. It Can Be Cut; the Question Is When",id:"9-it-can-be-cut-the-question-is-when",level:2},{value:"Coda: Home for Pork Jerky",id:"coda-home-for-pork-jerky",level:2},{value:"Notes",id:"notes",level:2}];function l(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"where-does-the-chaos-go-2-the-monster-becomes-a-seat",children:"Where Does the Chaos Go? (2): The Monster Becomes a Seat"})}),"\n",(0,o.jsx)(t.h2,{id:"a-dream-a-legacy-system-and-whether-staying-counts-as-winning",children:"A dream, a legacy system, and whether staying counts as winning"}),"\n",(0,o.jsx)(t.p,{children:"@Mythogen Engine \xb7 Nov 23, 2026"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsxs)(t.em,{children:['The previous article, "',(0,o.jsx)(t.a,{href:"/en/docs/chaos-series/freedom-and-lossless-integration",children:"You Can't Have Both Freedom and Lossless Integration"}),'," argued that the gap between promise and reality lands first in Excel, and that once a company cleans up, the gap moves into the organization, where no one can see it. This article asks what it becomes after settling there for ten or twenty years.']})}),"\n",(0,o.jsx)(t.h2,{id:"prologue-a-sleeper-carriage",children:"Prologue: A Sleeper Carriage"}),"\n",(0,o.jsx)(t.p,{children:"When I woke that day, I remembered only fragments of the dream."}),"\n",(0,o.jsx)(t.p,{children:'The first was rushing for a train. Instead of going through the mall, I took a path through the grass outside it. It was not a real road, just a shortcut worn by feet. The path led to a station called "Hong Kong Station," but in the dream that was not really its name; it was originally called "Sister Station." The station was actually two stations: one entered from the mall, one from outside, joined together, with two lines running side by side.'}),"\n",(0,o.jsx)(t.p,{children:"I boarded a sleeper train. The bed was large but not a private compartment; its edges were blurred. In the next bed was an old woman, perhaps twenty years older than me. I ignored her and went back to sleep. Halfway through the night she came over and tried to seduce me. When that failed, she changed, into a blonde Russian woman with a striking figure."}),"\n",(0,o.jsx)(t.p,{children:"In that moment I was completely lucid. I realized that what was in front of me was not human, or rather, was something wrong that I could not name. So even though the train was moving, I left."}),"\n",(0,o.jsx)(t.p,{children:"Between the train and home there was another part of the dream, which I forgot on waking and only recalled later. The scene shifted to a company in the middle of mass layoffs, keeping only the people who obeyed and were willing to cook the numbers. Problems kept multiplying and the legacy piled higher and higher, impossible to handle, yet we had to carry it on top of everything else. And the people best at vague bluster, the ones who had left behind the most legacy, became the most valuable. In the dream I even tried to find an explanation for all of it."}),"\n",(0,o.jsx)(t.p,{children:"In the last scene I got home, opened the fridge, took out the few leftover slices of pork jerky and a carton of boxed tea, and sat down to eat."}),"\n",(0,o.jsx)(t.p,{children:"What stayed with me after waking was not the plot but a question: in a company like that, even if you hold your position and stay, does that really count as winning?"}),"\n",(0,o.jsx)(t.p,{children:"To answer that, we have to start with the monster."}),"\n",(0,o.jsx)(t.h2,{id:"1-the-monster-was-not-always-a-monster",children:"1. The Monster Was Not Always a Monster"}),"\n",(0,o.jsx)(t.p,{children:"The most easily misunderstood point is this: systems like these are rarely wrong at the start."}),"\n",(0,o.jsx)(t.p,{children:"Take the battery management firmware I know well. The original design fit the needs, hardware limits and synchronization methods of its era, and it made sense. The problem is the evolution over the following ten or twenty years: nobody dares touch the old, so the new keeps getting piled on top. Like large enterprise software, all sorts of other things get grafted on along the way. Each layer has a reason when it is added, but features come to depend on one another, and those dependencies form rules that were never written down. Past a certain point, the difficulty is no longer any particular piece of code; it is that you cannot be sure which seemingly unrelated places a single change will affect."}),"\n",(0,o.jsx)(t.p,{children:'The classic case is "waiting." Old firmware is full of flows like this: send a command, wait five seconds, or some number of milliseconds, assume the other side has finished, and carry on. In the old environment, with stable load and predictable speeds, this could run without trouble for years.'}),"\n",(0,o.jsx)(t.p,{children:"But waiting is not synchronization. It is just an assumption that enough time has passed. Today's chips, architectures and communication methods are different, and synchronizing this way simply no longer works. Worse, other features have long since come to depend on the execution order this waiting creates: shorten it, remove it, or replace it with a real event acknowledgement, and you may expose a string of race conditions that had been hidden."}),"\n",(0,o.jsx)(t.p,{children:"Meanwhile, the organization chases innovation every year, and new features keep getting stacked on. New features are visible and can go into KPIs; cleaning up old dependencies is invisible and nobody rewards it. Every generation delivered, yet nobody was responsible for the overall complexity. Nothing was ever fully cleared, and after enough years it became a monster."}),"\n",(0,o.jsx)(t.p,{children:"It became a monster not because it has many features, but because the features, the outdated assumptions and the hidden dependencies are now tangled together, so any local change can have unpredictable consequences."}),"\n",(0,o.jsx)(t.h2,{id:"2-why-outsiders-dont-believe-you",children:"2. Why Outsiders Don't Believe You"}),"\n",(0,o.jsx)(t.p,{children:"The hardest part is explaining it to outsiders. The layperson's first reaction is usually \"you're the one who doesn't understand\": these people have done this for years, how could they have the basic concepts wrong?"}),"\n",(0,o.jsx)(t.p,{children:"Behind that reaction is an unproven assumption: that if a system keeps running, the people who designed it must have had the right concepts."}),"\n",(0,o.jsx)(t.p,{children:'In fact, a system can be kept alive by many things: staff filling gaps with manual procedures and exception handling, maintainers knowing what not to touch, new features deliberately routed around the deepest flaws, and a company that has invested so much that rewriting looks riskier than carrying on. To an outsider, as long as the results still come in and salaries still get paid, "it works." Nothing has blown up yet, and that gets mistaken for being right.'}),"\n",(0,o.jsx)(t.p,{children:'Seniority has the same problem. Twenty years can mean real experience, or it can mean only the memory of "where not to touch." Real experience makes a system easier and easier to understand and hand over; the other kind of seniority gains bargaining power as the system becomes harder to understand. Both people have twenty years in, and seniority by itself does not correct the way a person first understood the system.'}),"\n",(0,o.jsx)(t.p,{children:'So a proposition that ought to be tested by technical analysis is quietly turned into a proposition about personal ability: "Is it that you can\'t do it?" That substitution is much easier for the listener, because he does not need to understand the system. But for the person speaking, the real question has vanished.'}),"\n",(0,o.jsx)(t.h2,{id:"3-the-monster-writes-the-exam",children:"3. The Monster Writes the Exam"}),"\n",(0,o.jsx)(t.p,{children:"Much of this does not need to be so complicated. The reference designs that chip makers offer today are quite mature and widely accepted by the market. A system so complex that nobody understands it, if it is not tied to real requirements and verifiable benefits, is just complexity, and complexity is cost."}),"\n",(0,o.jsx)(t.p,{children:"The Samsung Note7 fires of ten years ago are often cited to show the risks of battery management. But the investigation Samsung published in early 2017 traced the root cause to separate design and manufacturing defects in two batches of batteries, not to the management software.\xb9 Battery management technology is quite mature today; where things actually go wrong is usually production and quality control. Piling ever more software on top does not buy safety."}),"\n",(0,o.jsx)(t.p,{children:'Yet when a reference design tries to replace the old system, it runs into a trap with almost no way out: write the legacy system\'s timing and architecture into the requirements, and the reference design is guaranteed to fail immediately, one hundred percent. That failure is then used to "prove" the reference design is flawed.'}),"\n",(0,o.jsx)(t.p,{children:"This is circular reasoning. A failed test does not show the reference design is defective; it only shows the exam was tailored to the old system. A five-second workaround, once written into the requirements, is laundered into a specification. More importantly, the people writing the requirements are often the very people whose value depends on the legacy system. The examiner, the candidate and the grader are the same people."}),"\n",(0,o.jsx)(t.p,{children:"To be fair, legacy systems sometimes stay for real reasons. For example, functional-safety certification has already been done, and switching means recertifying at high cost. But that is certification lock-in, not evidence that the old architecture is technically better. The two must be discussed separately, or the first will be used to cover for the second."}),"\n",(0,o.jsx)(t.p,{children:'The evidence on each side is not equal either. The reference design is backed by field data from many customers and large shipment volumes; the legacy system has only "nothing has happened at our company yet." The first is external validation; the second is survivorship bias.'}),"\n",(0,o.jsx)(t.p,{children:"Even so, it is very hard to prove who is right. The next section explains why."}),"\n",(0,o.jsx)(t.h2,{id:"4-evidence-has-to-be-bought-with-time",children:"4. Evidence Has to Be Bought With Time"}),"\n",(0,o.jsx)(t.p,{children:'Many battery management problems cannot be found in a lab. State-of-charge estimates only start to drift after hundreds of charge cycles; once cells age, balancing behaviour changes; combinations like low temperature, heavy load and half charge take a long time to hit. Users use devices differently, so problems appear at different times and in different forms. Pre-launch testing can only show "no problems in the short term," which is why most tests cannot really compare anything.'}),"\n",(0,o.jsx)(t.p,{children:"That makes the situation clearer: if the real evidence takes years to emerge, then at the moment of decision there is no evidence at all. What decides the outcome is where the burden of proof is placed."}),"\n",(0,o.jsx)(t.p,{children:"Organizations usually require the new option to prove it will not fail, while the old system never has to prove it has no problems. So the legacy system does not win the comparison; it never has to enter it, and wins by default."}),"\n",(0,o.jsx)(t.p,{children:"This is also why the reference design's market data matters more than any test: the market is itself a long-running field test across many kinds of use, just conducted at other customers. It is not perfect, and other people's usage cycles may differ from yours, but at least it was accumulated in real time. The legacy system's \"years without incident\" is much murkier: people have been patching it all along, so you cannot tell whether the architecture is sound or whether it has been held together by people cleaning up after it."}),"\n",(0,o.jsx)(t.p,{children:"The harder part is the other side. Some of those five-second waits and millisecond delays may really be scars from long-term use, experience paid for with real failures. The problem is that nobody ever recorded which delay was added for which incident. Experience and junk are mixed together, and even the people maintaining it cannot separate them. It is not that nobody wants to clean up; it is that the precondition for cleaning up, knowing why a thing is there, no longer exists."}),"\n",(0,o.jsx)(t.h2,{id:"5-the-documents-dont-match-reality",children:"5. The Documents Don't Match Reality"}),"\n",(0,o.jsx)(t.p,{children:"The most startling, most unbelievable problem in all of this is that the documents and data do not match the reality of what is actually running."}),"\n",(0,o.jsx)(t.p,{children:"This is the bottom layer. If the map itself is wrong, everything above was built on a wrong map: comparing legacy with the reference design, designing tests, citing market data, all of it compares documents, while what is actually running is a third thing that nobody has described."}),"\n",(0,o.jsx)(t.p,{children:'The most absurd part is that requirement, "must match legacy behaviour." Match which legacy? The one in the documents, or the one actually running? If the two differ, nobody can answer that requirement, yet it can still be used to sentence the reference design to death. You cannot even say clearly what the old system is, yet you demand the new one reproduce it one hundred percent.'}),"\n",(0,o.jsx)(t.p,{children:"Documents and reality usually part ways for more than one reason:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"Parameters were changed and patches applied in the field, and nobody wrote them back into the documents."}),"\n",(0,o.jsx)(t.li,{children:"Different batches and different customers run different versions, and the records describe only one."}),"\n",(0,o.jsx)(t.li,{children:"The documents were written for certification and audits, to get through them, not to describe the system. After passing, nobody has any incentive to keep them in sync."}),"\n",(0,o.jsx)(t.li,{children:"Calibration values are tuned by hand batch by batch; the real numbers exist only on the machines and in a few people's heads."}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"The third point connects directly to financialization: documents become proof of delivery rather than engineering knowledge. When the truth exists only in running machines and a few heads, those few people's bargaining power comes from exactly that. The less consistent the system, the more irreplaceable they are."}),"\n",(0,o.jsx)(t.p,{children:'This also explains why such problems always seem to erupt "suddenly." People make decisions from the documents and everything is fine, until some failure is opened up and it turns out the system everyone has understood for years is not the system that actually exists. What collapses at that moment is not one feature but the basis of everyone\'s past judgment.'}),"\n",(0,o.jsx)(t.h2,{id:"6-evidence-requires-power",children:"6. Evidence Requires Power"}),"\n",(0,o.jsx)(t.p,{children:"There is one more layer: inside a company, without C-level backing, it is simply impossible to look for proof."}),"\n",(0,o.jsx)(t.p,{children:'Finding evidence takes not only technical skill but access: pulling field data, returns and failure records, checking which firmware version each batch actually runs, borrowing test resources, getting other departments to cooperate, and having someone approve your time. Without senior backing, every one of these means asking someone. And the moment you ask, "looking for evidence" itself becomes a political act: in others\' eyes, you are not investigating the system, you are investigating them.'}),"\n",(0,o.jsx)(t.p,{children:"And the C-level usually has reasons not to back you:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"The timelines don't match."})," Evidence takes years of long-term use to emerge, while executives' tenures and reviews run by quarters and a few years. Funding an investigation that takes a long time and will most likely produce bad news does them no good."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Knowing means being responsible."}),' If it turns out the documents do not match what is actually running, that is an admission that past reports, certifications and even shipments rested on wrong data, which can mean recalls and legal liability. "Not knowing" is a form of protection.']}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:'The result: evidence can only be found with power, and the power is held by the people who least want the evidence to appear. It is not that nobody sees the problem; it is that the structure of the organization prevents "seeing" from becoming "proving."'}),"\n",(0,o.jsx)(t.p,{children:'Someone without authorization has only one route left: go outside the company for corroboration. I tried this myself. When I was sent to oversee regions, the numbers looked wrong to me but I had no authority to dig in, so I could only research online and ask customers directly to check the figures. The problem is that outside corroboration is exactly the kind of evidence an organization can most easily dismiss with "you don\'t understand the internal situation."'}),"\n",(0,o.jsx)(t.p,{children:"In a structure like this, the only evidence nobody can stop from appearing is the incident itself. It needs no one's authorization, but it always arrives at the worst possible time."}),"\n",(0,o.jsx)(t.h2,{id:"7-bad-money-drives-out-good-only-under-certain-conditions",children:"7. Bad Money Drives Out Good Only Under Certain Conditions"}),"\n",(0,o.jsx)(t.p,{children:"At this point it is natural to ask: is this just how the world works? There are so many companies like this, and so many people manage to work in them. If bad money driving out good is still society's survival rule, should we simply accept it as rational?"}),"\n",(0,o.jsx)(t.p,{children:"Common is not the same as justified. Being able to explain why something happens and conceding that it is right are two different things."}),"\n",(0,o.jsx)(t.p,{children:"Gresham's law originally held because the law forced two kinds of money to circulate at the same face value: when the market is not allowed to distinguish quality, people hoard the good money and spend the bad. Without that compulsion, people can price freely by quality, and the result reverses: good money drives out bad, which economists call Thiers' law.\xb3"}),"\n",(0,o.jsx)(t.p,{children:'Inside a company it is the same. For the bad to beat the good, the organization must be unable to tell them apart: evidence cannot be found, documents do not match reality, acceptance criteria are written by those with a stake, and nobody is authorized to check. The previous sections describe exactly how this "ban on telling apart" is built, step by step. So it is not a universal law of society, but a local rule within a certain kind of structure.'}),"\n",(0,o.jsx)(t.p,{children:'One misunderstanding needs care here: intense competition does not mean the ability to tell apart. Competition in the laptop market is fierce, but it is over a shrinking pie. When the pie shrinks, selling a few more machines is no longer enough, so competition shifts from "is the product good to use" to "how is the label defined."'}),"\n",(0,o.jsx)(t.p,{children:'The AI PC is the classic example. Many people hear "AI PC" and think of a computer that can run, or even train, large language models locally. In 2024, Microsoft led in defining it as the Copilot+ PC: the threshold was an NPU of at least 40 TOPS, the first machines all used ARM-based Snapdragon X chips, and qualifying chips from the x86 camp came later.\xb2 An NPU at that level mainly runs small-model inference and features like Copilot; running large models locally still depends on the GPU and video memory, to say nothing of training. The platform holds the power of definition, manufacturers fight inside that definition, and users pay a premium for a label whose value they cannot verify, at a high price.'}),"\n",(0,o.jsx)(t.p,{children:"The label works like the legal face value in Gresham's law: however much the machine actually helps you, with the label it sells at the same premium. The fiercer the competition, the more everyone competes on labels and spec sheets rather than on the difference you feel in real use."}),"\n",(0,o.jsx)(t.p,{children:'So the condition for the bad beating the good should be stated as: competition happens along dimensions the user cannot verify. It is the same structure as the battery firmware, moved into the consumer market. The spec sheet and certification are the "documents"; what the user experiences every day is the "running reality"; and the gap between the two is the source of the premium.'}),"\n",(0,o.jsx)(t.h2,{id:"8-whether-people-fight-depends-on-room",children:"8. Whether People Fight Depends on Room"}),"\n",(0,o.jsx)(t.p,{children:"I spent most of my career in companies that were expanding, yet blatant infighting was concentrated in just one of them. That does not mean that company was uniquely bad. Whether people fight depends on whether there is room not to."}),"\n",(0,o.jsx)(t.p,{children:"In an expansion phase, the pie is growing, and there are always new markets, new product lines and new positions. Someone who wants to move up can open new territory of their own without grabbing what is in someone else's hands. External pressure also means everyone has to fight outward together to eat, so infighting costs too much. People do not refrain from fighting because they are especially good; they refrain because not fighting is a real option."}),"\n",(0,o.jsx)(t.p,{children:'Of course, expansion only provides the conditions for not fighting; it does not guarantee there will be no infighting. I once saw a mainland supplier deliberately set up internal rivals even while it was expanding, believing that "competition breeds progress." The conditions may exist, but it still depends on how people use them.'}),"\n",(0,o.jsx)(t.p,{children:"When the pie shrinks, that option disappears. There are no new positions; for you to go up, someone has to come down, and everyone is pushed into a zero-sum game. At that point, fighting is no longer a matter of personality but the only way to stay."}),"\n",(0,o.jsx)(t.p,{children:"This is also when legacy changes meaning. In a shrinking organization, controlling a system nobody understands is the same as occupying a position nobody can take from you. The monster itself has become a seat."}),"\n",(0,o.jsx)(t.p,{children:"The same logic holds at the industry level: the laptop pie is shrinking, so manufacturers no longer compete to grow the market but to fit labels the platform defines, just as people inside companies compete for positions. The same group of people can cooperate in an expansion phase and tear each other down in a contraction. When people see infighting, they usually blame human nature or a particular bad actor, but what really decides the outcome is room."}),"\n",(0,o.jsx)(t.h2,{id:"9-it-can-be-cut-the-question-is-when",children:"9. It Can Be Cut; the Question Is When"}),"\n",(0,o.jsx)(t.p,{children:'But "nobody can take it from you" is only temporary. The seat is not safe; it is only deferred. Legacy can in fact be cut. The only questions are when a company is willing to cut it, and whether it avoids cutting for the sake of cutting.'}),"\n",(0,o.jsx)(t.p,{children:"Many companies drag it out until they have no choice, then force it, and the result is a mess. Every year of delay raises the cost: the people who understood why those delays exist leave one by one, the gap between documents and running reality widens, new features keep getting stacked on, and the dependencies tangle tighter. When it finally must be cut, perhaps after an incident, a new boss, or a financial crunch, nobody knows what they are cutting anymore. One cut, and every connected dependency snaps."}),"\n",(0,o.jsx)(t.p,{children:"The other mistake is cutting for the sake of cutting: starting from cost, deciding what to cut from the financial statements, and ignoring the dependencies inside."}),"\n",(0,o.jsx)(t.p,{children:"Both mistakes lack the same thing: in both, the cut is made without understanding what is being cut. One is too late, the other too crude."}),"\n",(0,o.jsx)(t.p,{children:"The most ironic part is the timing. The best time to cut legacy is when people still understand the system and there are still resources to migrate slowly, which is to say, during expansion. But during expansion everyone is busy adding things; adding has KPIs, cleaning up has no reward, and nobody wants to cut. In contraction it must be cut, but by then there is no room, no knowledge, and nobody willing to approve the time to do it carefully."}),"\n",(0,o.jsx)(t.p,{children:"When the conditions for cutting are best, nobody wants to cut; when it truly must be cut, the conditions are gone. Many companies do know they need to clean up; it is just that the window for cleaning up closed long ago, when they felt it least necessary."}),"\n",(0,o.jsx)(t.h2,{id:"coda-home-for-pork-jerky",children:"Coda: Home for Pork Jerky"}),"\n",(0,o.jsx)(t.p,{children:"Looking back at the dream, many of its images fall into place."}),"\n",(0,o.jsx)(t.p,{children:'The station called "Hong Kong Station" but originally named "Sister Station" has a single name, yet inside it is two stations joined, with two lines running in parallel, like the old and new layers of an architecture bolted together. The thing that changed from an old woman into a blonde is the same old thing in a new skin, coming back again, just like the new features stacked on every year under the banner of "innovation," with the same five-second synchronization underneath. And that line in the dream, "that is not human," is the judgment of someone who has seen through the skin.'}),"\n",(0,o.jsx)(t.p,{children:"As for whether staying counts as winning, I want to look at three kinds of winning and losing separately:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Winning inside the organization:"})," Did you keep your position, pay, power and resources?"]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Winning professionally:"})," Did you make the system more correct, more reliable, easier to maintain?"]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Winning personally:"})," Were the time you gave and the risks you took matched by what you got back?"]}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"These three can come out completely opposite. A person can keep their position while the system keeps deteriorating; can be professionally right and still leave because they could not persuade the organization; or can choose to leave, keeping their own time while paying the price in income, career and others' opinions."}),"\n",(0,o.jsx)(t.p,{children:'Many people who stay inside do not agree with it. There is a mortgage to pay and children to raise, and the job market outside is just as cut-throat, so staying can be a rational choice. Understanding why they stay and defending the structure are two different things. A person can keep working inside it without handing over their own standards of judgment, and without treating the structure as their own defect. The real danger is that after enough years you lose even the sense that "this place is not normal," and mistake a way of surviving for the truth.'}),"\n",(0,o.jsx)(t.p,{children:"At the end of the dream I did not linger over that bed. I went home, opened the fridge, ate the last few slices of pork jerky and drank a carton of boxed tea. It was no feast; there was not much of it and it tasted plain. But it was real, and it was mine."}),"\n",(0,o.jsx)(t.p,{children:"However huge the monster outside, however secure that seat, neither is mine. Those few slices of pork jerky in the fridge are."}),"\n",(0,o.jsx)(t.p,{children:"The next article is about the people who guard that seat: where they come from, and why the worse the problem gets, the higher they rise."}),"\n",(0,o.jsxs)(t.p,{children:['Next: "',(0,o.jsx)(t.a,{href:"/en/docs/chaos-series/problem-worse-person-promoted",children:"Each Time the Problem Gets Worse, Someone Gets Promoted"}),'."']}),"\n",(0,o.jsx)(t.h2,{id:"notes",children:"Notes"}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.a,{href:"https://www.notebookcheck.net/Samsung-Galaxy-Note-7-investigation-results-are-now-public.193102.0.html",children:'"Samsung Galaxy Note 7 investigation results are now public," Notebookcheck'}),", 23 January 2017. Samsung and three independent organizations examined the hardware, software and related processes and concluded that batteries from two suppliers each had defects: one batch was a new design mass-produced without adequate testing, the other was rushed and missing insulation tape. Both led to short circuits between the electrodes."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.a,{href:"https://www.tomshardware.com/software/windows/microsoft-copilot-pcs-all-we-know",children:'"Copilot+ PCs: All we know," Tom\'s Hardware'}),", May 2024. The requirements were an NPU of at least 40 TOPS, 16GB of memory and 256GB of storage; the first machines all used Snapdragon X Elite / X Plus, and AMD and Intel chips at the time fell short."]}),"\n",(0,o.jsxs)(t.li,{children:["On Gresham's law depending on a legally fixed ratio, see ",(0,o.jsx)(t.a,{href:"https://moneyness.ca/2014/06/when-good-drives-out-bad.html",children:'"When good drives out bad," Moneyness'}),"; Thiers' law was named by Peter Bernholz, see Peter Bernholz, ",(0,o.jsx)(t.em,{children:"Monetary Regimes and Inflation"}),", Edward Elgar, 2003."]}),"\n"]})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(96540);const a={},s=o.createContext(a);function i(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);